function perfectpixel_purchased_quantities( $user_id ) {
	$key  = 'perfectpixel_purchased_qty_' . $user_id;
	$data = get_transient( $key );
	if ( false === $data ) {
		$data = array();
		foreach ( wc_get_orders( array( 'customer_id' => $user_id, 'status' => wc_get_is_paid_statuses(), 'limit' => -1 ) ) as $order ) {
			foreach ( $order->get_items() as $item ) {
				foreach ( array_filter( array( $item->get_product_id(), $item->get_variation_id() ) ) as $id ) {
					$data[ $id ] = ( $data[ $id ] ?? 0 ) + (int) $item->get_quantity();
				}
			}
		}
		set_transient( $key, $data, DAY_IN_SECONDS );
	}
	return (array) $data;
}

function perfectpixel_purchased_count_shortcode( $atts ) {
	$atts = shortcode_atts( array( 'id' => 0 ), $atts );
	$id   = absint( $atts['id'] );
	if ( ! $id || ! is_user_logged_in() ) {
		return '0';
	}
	$data = perfectpixel_purchased_quantities( get_current_user_id() );
	return esc_html( number_format_i18n( $data[ $id ] ?? 0 ) );
}

function perfectpixel_purchased_count_flush( $order_id, $from, $to, $order ) {
	if ( $order && $order->get_customer_id() ) {
		delete_transient( 'perfectpixel_purchased_qty_' . $order->get_customer_id() );
	}
}
